public class Study {public interface Property<T>{boolean test(T value);}public static <T> int count(T[] values,Property<? super T> property){return Math.toIntExact(new Counter().matching(values,property));}static class Positive implements Property<Integer>{public boolean test(Integer x){return x>0;}}static class HasDot implements Property<String>{public boolean test(String x){return x.indexOf('.')>=0;}}void main(){System.out.println(count(new Integer[]{-1,2,3},new Positive()));System.out.println(count(new String[]{"a.b","plain","."},new HasDot()));}}
class Counter {<T> long matching(T[] values,Study.Property<? super T> property){long n=0;for(T x:values)if(property.test(x))n++;return n;}}
